async function run() {
  const from = now();
  const to = dates.addHours(from, 1);
  const events = await calendar.events({ from, to });
  if (!events || events.length === 0) {
    log("Nenhuma reunião no calendário no período informado");
    return;
  }
  const upcoming = events.filter(ev => {
    if (!ev.start || ev.start.length <= 10) return false; // evento de dia inteiro, sem horário
    return !dates.isBefore(ev.start, from) && dates.isBefore(ev.start, to);
  });
  if (upcoming.length === 0) {
    log("Nenhuma reunião começa na próxima hora");
    return;
  }
  for (const ev of upcoming) {
    const time = dates.format(ev.start, "HH:mm");
    const location = ev.location ? ev.location : "sem local";
    const attendees = (ev.attendees && ev.attendees.length) ? ev.attendees.join(", ") : "sem participantes";
    const text = `⏰ ${time} ${ev.title} — ${location} — ${attendees}`;
    await notify.send({ text });
  }
}
